bool Http::isRobloxSite(const char* url)
{
	CUrl crack;
	crack.CrackUrl(url);

	switch (crack.GetScheme()) {
	case ATL_URL_SCHEME_FTP:
	case ATL_URL_SCHEME_HTTP:
	case ATL_URL_SCHEME_HTTPS: {
		CString hostName = crack.GetHostName();
		hostName.MakeLower();
		if (hostName.Right(10) == "roblox.com") {
			return true;
		}
		return false;
	}

	default:
		return false;
	}
}

} // namespace RBX

